package com.varnalabs.mobile;
import java.io.*;import java.net.*;import java.util.*;import org.json.*;
final class ServerClient58 {
 static volatile HttpURLConnection active;static void cancel(){HttpURLConnection c=active;if(c!=null)c.disconnect();}

 static Object call(MainActivity a,String endpoint,String token,String method,String route,String body)throws Exception{
  URI base=new URI(endpoint);String host=base.getHost();if(host==null||base.getUserInfo()!=null||base.getQuery()!=null||base.getFragment()!=null||!(base.getPath()==null||base.getPath().isEmpty()||base.getPath().equals("/")))throw new IOException("Enter only the server origin");
  boolean local=host.equals("localhost")||host.equals("127.0.0.1")||host.matches("192\\.168\\.\\d{1,3}\\.\\d{1,3}")||host.matches("10\\.\\d{1,3}\\.\\d{1,3}\\.\\d{1,3}")||host.matches("172\\.(1[6-9]|2[0-9]|3[01])\\..*");if(!base.getScheme().equals("https")&&!(base.getScheme().equals("http")&&local))throw new IOException("Use HTTPS for internet access, or a private LAN IP");
  if(!token.matches("[a-f0-9]{64}")||!method.matches("GET|POST|DELETE")||!route.matches("/v1/(status|uploads|jobs|jobs/[a-f0-9-]{36}(/result)?)"))throw new IOException("Invalid connection request");
  HttpURLConnection c=(HttpURLConnection)new URL(endpoint.replaceAll("/$","")+route).openConnection();active=c;c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(60000);c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer "+token);
  try{if(method.equals("POST")){c.setDoOutput(true);if(route.equals("/v1/uploads")){File file=a.mediaFile(body);c.setRequestProperty("Content-Type","application/octet-stream");c.setFixedLengthStreamingMode(file.length());try(InputStream in=new FileInputStream(file);OutputStream out=c.getOutputStream()){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}else{byte[] b=body.getBytes("UTF-8");c.setRequestProperty("Content-Type","application/json");c.setFixedLengthStreamingMode(b.length);try(OutputStream out=c.getOutputStream()){out.write(b);}}}
   int status=c.getResponseCode();if(status<200||status>=300){InputStream err=c.getErrorStream();ByteArrayOutputStream b=new ByteArrayOutputStream();if(err!=null)try(InputStream in=err){byte[] buffer=new byte[1024];int n;while((n=in.read(buffer))!=-1&&b.size()<8192)b.write(buffer,0,n);}throw new IOException("Server "+status+": "+b.toString("UTF-8"));}
   String type=c.getContentType();if(type!=null&&type.startsWith("application/json")){ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(b.size()+n>4*1024*1024)throw new IOException("Response too large");b.write(buffer,0,n);}}return new JSONObject(b.toString("UTF-8"));}
   String id=UUID.randomUUID().toString();File dir=new File(a.getFilesDir(),"media");dir.mkdirs();File file=new File(dir,id);try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>512L*1024*1024)throw new IOException("Result too large");out.write(buffer,0,n);}}catch(Exception e){file.delete();throw e;}a.getPreferences(0).edit().putString("mime:"+id,type).apply();JSONObject result=new JSONObject();result.put("id",id);result.put("name",type!=null&&type.startsWith("video/")?"Proxy.mp4":"Subtitles.srt");result.put("type",type);result.put("url",MainActivity.ORIGIN+"/media/"+id);result.put("bytes",file.length());return result;
  }finally{if(active==c)active=null;c.disconnect();}
 }
}
